/**
 * Closed workspaces are gone for every caller. A missing row is not closed —
 * the caller still owes the not-found error.
 */
export function assertOrgIsLive(orgId: OrgId): void {
  const row = getDb()
    .select({ archivedAt: organizations.archivedAt })
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  if (row && isArchived({ archivedAt: row.archivedAt })) {
    throw new AlreadyArchivedError("Organization", orgId);
  }
}

