/** Drops deliveries that were still queued when the workspace closed. */
export async function discardPendingDeliveries(orgId: OrgId): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: "workspace is closed",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.status, "pending"),
      ),
    )
    .run();
}

